const filename = env.get("SITE_CONFIG_PATH") || "/data/config/site.solis.json";
msg.filename = filename;
return msg;

const store = env.get("GLOBAL_STORE") || "default";

function fail(message) {
    node.status({ fill: "red", shape: "ring", text: message });
    return [null, { payload: { ok: false, error: message } }];
}

const cfg = msg.payload;
if (!cfg || typeof cfg !== "object") return fail("site config is not an object");
if (!cfg.site) return fail("missing site");
if (!Array.isArray(cfg.iec104Points)) return fail("missing iec104Points[]");
if (!Array.isArray(cfg.iec104Commands)) cfg.iec104Commands = [];
if (!Array.isArray(cfg.modbusReads)) cfg.modbusReads = [];
if (!cfg.mqttPayload) cfg.mqttPayload = { fields: [] };

const deviceId = cfg.site.deviceId || env.get("DEVICE_ID") || "DEVICE";
cfg.site.deviceId = deviceId;

function normalizePoint(p, isCommand) {
    const out = Object.assign({}, p);
    if (!isCommand && out.name && !String(out.name).startsWith(deviceId + "_")) {
        out.name = `${deviceId}_${out.name}`;
    }
    return out;
}

const points = cfg.iec104Points.map(p => normalizePoint(p, false));
const commands = cfg.iec104Commands.map(p => normalizePoint(p, true));
const templates = points.concat(commands);

global.set("siteConfig", cfg, store);
global.set("iec104_templates", templates, store);

// Also set without explicit store for compatibility with older nodes.
global.set("siteConfig", cfg);
global.set("iec104_templates", templates);

msg.siteConfig = cfg;
msg.iec104_templates = templates;
msg.payload = {
    ok: true,
    siteId: cfg.site.siteId,
    deviceId,
    pointCount: points.length,
    commandCount: commands.length,
    modbusReadCount: cfg.modbusReads.length
};

node.status({
    fill: "green",
    shape: "dot",
    text: `${deviceId}: ${templates.length} IEC104 mappings`
});

return [msg, null];

const store = env.get("GLOBAL_STORE") || "default";
const cfg = global.get("siteConfig", store) || global.get("siteConfig") || {};
const reads = Array.isArray(cfg.modbusReads) ? cfg.modbusReads : [];
const deviceId = (cfg.site && cfg.site.deviceId) || env.get("DEVICE_ID") || "DEVICE";

if (!reads.length) {
    node.status({ fill: "yellow", shape: "ring", text: "no modbusReads[]" });
    return null;
}

const batchId = `modbus-${Date.now()}`;
const out = reads.map((r, index) => ({
    payload: {
        fc: Number(r.fc),
        unitid: Number(r.unitid),
        address: Number(r.address),
        quantity: Number(r.quantity)
    },
    readDef: r,
    deviceId,
    parts: {
        id: batchId,
        index,
        count: reads.length,
        type: "array"
    }
}));

node.status({ fill: "blue", shape: "dot", text: `${reads.length} read requests` });
return [out];

const store = env.get("GLOBAL_STORE") || "default";

function toRegisters(msg) {
    if (Array.isArray(msg.payload)) return msg.payload;
    if (msg.payload && Array.isArray(msg.payload.data)) return msg.payload.data;
    if (msg.responseBuffer && Array.isArray(msg.responseBuffer.data)) return msg.responseBuffer.data;
    if (msg.payload && Buffer.isBuffer(msg.payload.buffer)) {
        const b = msg.payload.buffer;
        const regs = [];
        for (let i = 0; i + 1 < b.length; i += 2) regs.push(b.readUInt16BE(i));
        return regs;
    }
    if (Buffer.isBuffer(msg.payload)) {
        const regs = [];
        for (let i = 0; i + 1 < msg.payload.length; i += 2) regs.push(msg.payload.readUInt16BE(i));
        return regs;
    }
    return null;
}

function regBuffer(regs, order) {
    const r0 = Number(regs[0] || 0);
    const r1 = Number(regs[1] || 0);
    const b = Buffer.alloc(4);
    const mode = String(order || "BE").toUpperCase();

    // BE/ABCD: reg0 high-low, reg1 high-low.
    // LE/CDAB/LE_WORD: reg1 high-low, reg0 high-low.
    // BADC: reg0 low-high, reg1 low-high.
    // DCBA/LE_BYTE_WORD: reg1 low-high, reg0 low-high.
    if (mode === "LE" || mode === "CDAB" || mode === "LE_WORD") {
        b.writeUInt16BE(r1, 0); b.writeUInt16BE(r0, 2);
    } else if (mode === "BADC") {
        b[0] = r0 & 0xff; b[1] = (r0 >> 8) & 0xff;
        b[2] = r1 & 0xff; b[3] = (r1 >> 8) & 0xff;
    } else if (mode === "DCBA" || mode === "LE_BYTE_WORD") {
        b[0] = r1 & 0xff; b[1] = (r1 >> 8) & 0xff;
        b[2] = r0 & 0xff; b[3] = (r0 >> 8) & 0xff;
    } else {
        b.writeUInt16BE(r0, 0); b.writeUInt16BE(r1, 2);
    }
    return b;
}

function parseValue(regs, def) {
    const datatype = String(def.datatype || "uint16").toLowerCase();
    const order = def.byteOrder || def.wordOrder || "BE";

    if (datatype === "bool" || datatype === "boolean" || Number(def.fc) === 1 || Number(def.fc) === 2) {
        return regs[0] ? 1 : 0;
    }

    if (datatype === "int16") return Buffer.from([(regs[0] >> 8) & 0xff, regs[0] & 0xff]).readInt16BE(0);
    if (datatype === "uint16") return Number(regs[0]);

    const b = regBuffer(regs, order);

    if (datatype === "int32") return b.readInt32BE(0);
    if (datatype === "uint32") return b.readUInt32BE(0);
    if (datatype === "float" || datatype === "float32" || datatype === "floatbe" || datatype === "floatle") {
        return b.readFloatBE(0);
    }

    throw new Error(`unsupported datatype: ${datatype}`);
}

try {
    const def = msg.readDef;
    if (!def || !def.name) throw new Error("missing msg.readDef.name");

    const regs = toRegisters(msg);
    if (!regs || !regs.length) throw new Error(`no Modbus data for ${def.name}`);

    let value = parseValue(regs, def);
    const scale = Number(def.readScale ?? 1);
    const offset = Number(def.offset ?? 0);
    if (Number.isFinite(scale)) value *= scale;
    if (Number.isFinite(offset)) value += offset;

    const deviceId = msg.deviceId || env.get("DEVICE_ID") || "DEVICE";
    const fullKey = `${deviceId}_${def.name}`;

    global.set(fullKey, value, store);
    global.set(fullKey, value);

    msg.payload = { [fullKey]: value };
    msg.topic = fullKey;
    msg.value = value;

    node.status({ fill: "green", shape: "dot", text: `${fullKey}=${value}` });
    return [msg, null];
} catch (err) {
    node.status({ fill: "red", shape: "ring", text: err.message });
    msg.payload = { ok: false, error: err.message, readDef: msg.readDef };
    return [null, msg];
}

const store = env.get("GLOBAL_STORE") || "default";
const t = (msg.status && msg.status.text) ? String(msg.status.text).toLowerCase() : String(msg.payload || "").toLowerCase();

let online = global.get("modbus_online", store);
let eventPayload = "status-check";

if (t.includes("reconnecting") || t.includes("timeout") || t.includes("error") || t === "initialize" || t.includes("not connected")) {
    online = false;
    eventPayload = "invalid";
} else if (t.includes("connected") || t.includes("active") || t.includes("queue empty")) {
    online = true;
    eventPayload = "online";
}

global.set("modbus_online", !!online, store);
global.set("modbus_online", !!online);

node.status({
    fill: online ? "green" : "red",
    shape: "dot",
    text: online ? "Modbus online" : "Modbus offline"
});

msg.payload = eventPayload;
msg.modbus_online = !!online;
return msg;

const store = env.get("GLOBAL_STORE") || "default";
const cfg = global.get("siteConfig", store) || global.get("siteConfig") || {};
const templates = global.get("iec104_templates", store) || global.get("iec104_templates") || [];
const deviceId = (cfg.site && cfg.site.deviceId) || env.get("DEVICE_ID") || "DEVICE";

const pointTemplates = (Array.isArray(cfg.iec104Points) && cfg.iec104Points.length)
    ? cfg.iec104Points.map(p => {
        const out = Object.assign({}, p);
        if (out.name && !String(out.name).startsWith(deviceId + "_")) out.name = `${deviceId}_${out.name}`;
        return out;
      })
    : templates.filter(t => t.type && !String(t.type).startsWith("C_"));

const invalidRequest = msg.payload === "invalid" || msg.modbus_online === false || global.get("modbus_online", store) === false;
const outMsgs = [];

function roundByScale(num, scale) {
    if (!Number.isFinite(num)) return num;
    if (!scale || scale === 1) return num;
    const decimals = Math.max(0, Math.round(-Math.log10(Math.abs(scale))));
    return Number(num.toFixed(decimals));
}

for (const entry of pointTemplates) {
    if (!entry || !entry.name || !entry.type || entry.address === undefined) continue;
    if (String(entry.type).startsWith("C_")) continue;

    const raw = global.get(entry.name, store);
    const scale = Number(entry.scale ?? 1);

    let value = 0;
    let qualifier = "IEC60870_QUALITY_GOOD";

    if (invalidRequest || raw === undefined || raw === null || Number.isNaN(Number(raw))) {
        qualifier = "IEC60870_QUALITY_INVALID";
    } else {
        value = roundByScale(Number(raw) * scale, scale);
        if (entry.type === "M_SP_TB_1" || entry.type === "M_SP_NA_1") value = value ? 1 : 0;
    }

    outMsgs.push({
        payload: {
            type: entry.type,
            address: Number(entry.address),
            value,
            qualifier
        },
        pointName: entry.name
    });
}

node.status({
    fill: invalidRequest ? "yellow" : "green",
    shape: "dot",
    text: `${outMsgs.length} IEC104 points${invalidRequest ? " INVALID" : ""}`
});

return [outMsgs];

if (typeof msg.payload === "string") {
    if (!msg.payload.endsWith("\n")) msg.payload += "\n";
    return msg;
}

msg.payload = JSON.stringify(msg.payload) + "\n";
return msg;

const text = String(msg.payload || "");
const lines = text.split("\n").map(s => s.trim()).filter(s => s.length > 2);
return [lines.map(line => ({ payload: line }))];

const store = env.get("GLOBAL_STORE") || "default";
const templates = global.get("iec104_templates", store) || global.get("iec104_templates") || [];
const cmd = msg.payload || {};

// Only execute should write to Modbus. Select/check events are intentionally ignored.
if (cmd.action && cmd.action !== "execute") {
    node.status({ fill: "grey", shape: "ring", text: `ignored action=${cmd.action}` });
    return null;
}

const matched = templates.find(e => e.type === cmd.type && Number(e.address) === Number(cmd.address));

if (!matched) {
    node.warn(`No command mapping for type=${cmd.type}, IOA=${cmd.address}`);
    node.status({ fill: "red", shape: "ring", text: "mapping not found" });
    return null;
}

if (matched.datatype === "bool" || matched.datatype === "boolean") {
    const b = !!(cmd.value === true || cmd.value === 1 || cmd.value === "1");
    const coilOn = (matched.coilOn !== undefined) ? matched.coilOn : 1;
    const coilOff = (matched.coilOff !== undefined) ? matched.coilOff : 0;

    msg.payload = {
        fc: 5,
        unitid: Number(matched.unitid),
        address: Number(matched.modbusAddress),
        value: b ? coilOn : coilOff,
        quantity: 1
    };

    node.status({ fill: "blue", shape: "dot", text: `${matched.name}=${b ? 1 : 0}` });
    return msg;
}

const scale = (matched.scale != null) ? Number(matched.scale) : 1;
const value = Number(cmd.value) * scale;
const buf = Buffer.alloc(4);

const outPayload = {
    fc: 16,
    unitid: Number(matched.unitid),
    address: Number(matched.modbusAddress),
    quantity: 2,
    value: []
};

switch (String(matched.datatype || "").toLowerCase()) {
    case "int16":
    case "uint16":
        outPayload.fc = 6;
        outPayload.quantity = 1;
        outPayload.value = Math.round(value);
        break;

    case "int32":
        buf.writeInt32LE(Math.round(value));
        if (matched.byteOrder === "LEswap" || matched.byteOrder === "LE16swap") {
            outPayload.value = [buf.readUInt16LE(2), buf.readUInt16LE(0)];
        } else if (matched.byteOrder === "LE") {
            outPayload.value = [buf.readUInt16LE(0), buf.readUInt16LE(2)];
        } else {
            buf.writeInt32BE(Math.round(value));
            outPayload.value = [buf.readUInt16BE(0), buf.readUInt16BE(2)];
        }
        break;

    case "uint32":
        buf.writeUInt32LE(Math.round(value));
        if (matched.byteOrder === "LEswap" || matched.byteOrder === "LE16swap") {
            outPayload.value = [buf.readUInt16LE(2), buf.readUInt16LE(0)];
        } else if (matched.byteOrder === "LE") {
            outPayload.value = [buf.readUInt16LE(0), buf.readUInt16LE(2)];
        } else {
            buf.writeUInt32BE(Math.round(value));
            outPayload.value = [buf.readUInt16BE(0), buf.readUInt16BE(2)];
        }
        break;

    case "float":
    case "float32":
        if (matched.byteOrder === "LEswap" || matched.byteOrder === "LE16swap") {
            buf.writeFloatLE(value);
            outPayload.value = [buf.readUInt16LE(2), buf.readUInt16LE(0)];
        } else if (matched.byteOrder === "LE") {
            buf.writeFloatLE(value);
            outPayload.value = [buf.readUInt16LE(0), buf.readUInt16LE(2)];
        } else {
            buf.writeFloatBE(value);
            outPayload.value = [buf.readUInt16BE(0), buf.readUInt16BE(2)];
        }
        break;

    default:
        node.error(`Unsupported datatype: ${matched.datatype}`, msg);
        node.status({ fill: "red", shape: "ring", text: `bad datatype ${matched.datatype}` });
        return null;
}

msg.payload = outPayload;
node.status({ fill: "blue", shape: "dot", text: `${matched.name} write` });
return msg;

const store = env.get("GLOBAL_STORE") || "default";
const v = msg.payload;
const online = !(v === false || v === 0 || v === "0" || String(v).toLowerCase() === "false");
global.set("internetAvailable", online, store);
global.set("internetAvailable", online);
node.status({ fill: online ? "green" : "red", shape: "dot", text: online ? "online" : "offline" });
msg.payload = { internetAvailable: online };
return msg;

const store = env.get("GLOBAL_STORE") || "default";
const cfg = global.get("siteConfig", store) || global.get("siteConfig") || {};
const templates = global.get("iec104_templates", store) || global.get("iec104_templates") || [];
const site = cfg.site || {};
const deviceId = site.deviceId || env.get("DEVICE_ID") || "DEVICE";
const fields = (cfg.mqttPayload && Array.isArray(cfg.mqttPayload.fields)) ? cfg.mqttPayload.fields : [];

function roundByScale(num, scale) {
    if (!Number.isFinite(num)) return num;
    if (!scale || scale === 1) return num;
    const decimals = Math.max(0, Math.round(-Math.log10(Math.abs(scale))));
    return Number(num.toFixed(decimals));
}

const result = {};
for (const field of fields) {
    const fullKey = String(field).startsWith(deviceId + "_") ? field : `${deviceId}_${field}`;
    const raw = global.get(fullKey, store);
    const template = templates.find(t => t.name === fullKey);
    const scale = Number((template && template.scale !== undefined) ? template.scale : 1);
    if (raw === undefined || raw === null || Number.isNaN(Number(raw))) {
        result[field.replace(deviceId + "_", "")] = null;
    } else {
        result[field.replace(deviceId + "_", "")] = roundByScale(Number(raw) * scale, scale);
    }
}

msg.topic = env.get("MQTT_TOPIC") || (cfg.mqtt && cfg.mqtt.topic) || "";
msg.payload = [{
    name: site.siteName || site.siteId || deviceId,
    type: site.projectType || "104_SOL",
    ts: Math.floor(Date.now() / 1000),
    ...result
}];

const online = global.get("internetAvailable", store) === true;
let queue = flow.get("mqtt_queue") || [];
const maxQueueSize = Number(env.get("QUEUE_MAX_SIZE") || 10000);
const sampleIntervalMs = Number(env.get("QUEUE_SAMPLE_INTERVAL_SECONDS") || 300) * 1000;
const now = Date.now();
const lastQueueTime = flow.get("mqtt_last_queue_time") || 0;

const publishMsg = { topic: msg.topic, payload: msg.payload };

if (online && queue.length === 0) {
    node.status({ fill: "green", shape: "dot", text: "publish realtime" });
    return publishMsg;
}

if (!online && (now - lastQueueTime >= sampleIntervalMs)) {
    if (queue.length >= maxQueueSize) queue.shift();
    queue.push(publishMsg);
    flow.set("mqtt_queue", queue);
    flow.set("mqtt_last_queue_time", now);
    node.status({ fill: "yellow", shape: "ring", text: `queued ${queue.length}` });
} else if (online && queue.length > 0) {
    if (queue.length >= maxQueueSize) queue.shift();
    queue.push(publishMsg);
    flow.set("mqtt_queue", queue);
    node.status({ fill: "blue", shape: "ring", text: `queue pending ${queue.length}` });
} else {
    node.status({ fill: "grey", shape: "ring", text: `skip queue ${queue.length}` });
}

return null;

const store = env.get("GLOBAL_STORE") || "default";
const online = global.get("internetAvailable", store) === true;
let queue = flow.get("mqtt_queue") || [];

if (!online || queue.length === 0) {
    node.status({ fill: online ? "grey" : "red", shape: "ring", text: online ? "queue empty" : "offline" });
    return null;
}

const next = queue.shift();
flow.set("mqtt_queue", queue);
node.status({ fill: "green", shape: "dot", text: `flush, left ${queue.length}` });
return next;

const store = env.get("GLOBAL_STORE") || "default";
const cfg = global.get("siteConfig", store) || global.get("siteConfig") || {};
const deviceId = (cfg.site && cfg.site.deviceId) || env.get("DEVICE_ID") || "DEVICE";

const sourceShort = (cfg.snapshot && cfg.snapshot.source) || env.get("SNAPSHOT_SOURCE") || "a_Inv_D";
const targetShort = (cfg.snapshot && cfg.snapshot.target) || env.get("SNAPSHOT_TARGET") || "a_Inv_D1";

const sourceKey = String(sourceShort).startsWith(deviceId + "_") ? sourceShort : `${deviceId}_${sourceShort}`;
const targetKey = String(targetShort).startsWith(deviceId + "_") ? targetShort : `${deviceId}_${targetShort}`;

const toNum = v => {
    const n = Number(v);
    return Number.isFinite(n) ? n : NaN;
};

let val = toNum(msg.payload);
if (Number.isNaN(val)) val = toNum(global.get(sourceKey, store));

if (Number.isNaN(val)) {
    node.status({ fill: "red", shape: "ring", text: `no numeric ${sourceKey}` });
    return null;
}

global.set(targetKey, val, store);
global.set(`${targetKey}_ts`, Date.now(), store);
global.set(targetKey, val);
global.set(`${targetKey}_ts`, Date.now());

msg.payload = { [targetKey]: val, ts: Date.now() };
node.status({ fill: "green", shape: "dot", text: `${targetKey}=${val}` });
return msg;
